BEGIN;

DO $guard$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.baseset_materials
    WHERE id = 9007187463893765 AND code IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_10_MAT'
  ) THEN
    RAISE EXCEPTION 'fixture material id % is owned by another record', 9007187463893765;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.rm_formulas
    WHERE id = 9007187463893766 AND formual_code IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_10_FORM'
  ) THEN
    RAISE EXCEPTION 'fixture formula id % is owned by another record', 9007187463893766;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.wom_produce_tasks
    WHERE id = 9007187463893767
      AND (table_no IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_10_TASK_TN'
           OR produce_batch_num IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_10_BATCH')
  ) THEN
    RAISE EXCEPTION 'fixture WOM task id % is owned by another record', 9007187463893767;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.wom_wait_put_records
    WHERE id = 9007187463893768 AND task_id IS DISTINCT FROM 9007187463893767
  ) THEN
    RAISE EXCEPTION 'fixture WOM wait id % is owned by another task', 9007187463893768;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.wfm_task_pending
    WHERE id = 9007187463893769
      AND (table_info_id IS DISTINCT FROM 9007187463893767
           OR table_no IS DISTINCT FROM 'ADP_E2E_20260727_MES_FULL_CLOSED_10_TASK_TN')
  ) THEN
    RAISE EXCEPTION 'fixture workflow pending id % is owned by another task', 9007187463893769;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.wom_output_details d
    LEFT JOIN public.wom_proc_reports r ON r.id = d.head_id
    WHERE d.id = 9007187463893770
      AND r.task_id IS DISTINCT FROM 9007187463893767
  ) THEN
    RAISE EXCEPTION 'fixture output detail id % is owned by another task', 9007187463893770;
  END IF;
END
$guard$;

DELETE FROM public.wom_mat_outpt_records WHERE out_mat_detail_id = 9007187463893770;
DELETE FROM public.wom_output_details
 WHERE id = 9007187463893770
    OR head_id IN (SELECT id FROM public.wom_proc_reports WHERE task_id = 9007187463893767);
DELETE FROM public.wom_task_act_itemss WHERE produce_batch_num = 'ADP_E2E_20260727_MES_FULL_CLOSED_10_BATCH';
DELETE FROM public.wom_acti_exelogs WHERE task_id = 9007187463893767;
DELETE FROM public.wom_process_exelogs WHERE task_id = 9007187463893767;
DELETE FROM public.wom_task_actives WHERE task_id = 9007187463893767;
DELETE FROM public.wom_task_processes WHERE task_id = 9007187463893767;
DELETE FROM public.wom_produce_task_exelog WHERE task_id = 9007187463893767;
DELETE FROM public.wom_proc_reports WHERE task_id = 9007187463893767;
DELETE FROM public.wf_deal_info WHERE table_info_id = 9007187463893767;
DELETE FROM public.wfm_task_pending WHERE id = 9007187463893769 OR table_info_id = 9007187463893767;
DELETE FROM public.wom_wait_put_records WHERE id = 9007187463893768 OR task_id = 9007187463893767;
DELETE FROM public.wom_produce_tasks WHERE id = 9007187463893767;
DELETE FROM public.rm_formulas WHERE id = 9007187463893766;
DELETE FROM public.baseset_materials WHERE id = 9007187463893765;

COMMIT;
SELECT 'cleanup',
       (SELECT count(*) FROM public.wom_produce_tasks WHERE id = 9007187463893767),
       (SELECT count(*) FROM public.wom_wait_put_records WHERE task_id = 9007187463893767),
       (SELECT count(*) FROM public.rm_formulas WHERE id = 9007187463893766),
       (SELECT count(*) FROM public.baseset_materials WHERE id = 9007187463893765);

